<script setup lang="ts">
import { Award, LogOut, MapPin, Package, Settings, ShoppingBag, UserRound } from '@lucide/vue';
const config = useRuntimeConfig(); const active = ref('overview'); const loading = ref(true); const dashboard = ref<any>(null); const error = ref(''); const { accessToken, user, authHeaders, loadMe, logout } = useStorefront();
const statuses: Record<string,string> = { NEW:'Новый', CONFIRMED:'Подтверждён', PAYMENT_WAITING:'Ожидает оплату', PAID:'Оплачен', ASSEMBLING:'Собирается', SHIPPED:'Отправлен', DELIVERED:'Доставлен', CANCELLED:'Отменён', REFUNDED:'Возврат' };
onMounted(async () => { await loadMe(); if (!accessToken.value) return navigateTo('/login?return=/account'); try { dashboard.value = await $fetch('/storefront/dashboard', { baseURL: config.public.apiBase, headers: authHeaders.value }); } catch (e: any) { error.value = e?.data?.message || 'Не удалось загрузить личный кабинет'; } finally { loading.value = false; } });
function signOut() { logout(); navigateTo('/'); }
useSeoMeta({ title: 'Личный кабинет — SARKISIAN BRAND' });
</script>
<template><SiteShell><div class="sb-account-page"><div class="sb-account-head"><div><p>ЛИЧНЫЙ КАБИНЕТ</p><h1>{{ user?.firstName ? `${user.firstName}, добрый день` : 'Добрый день' }}</h1><span>Здесь собраны покупки, бонусы и персональные данные.</span></div><div class="sb-loyalty-mini"><Award :size="23" /><span><small>Бонусный баланс</small><b>{{ dashboard?.loyalty?.balance || 0 }} бонусов</b></span></div></div><div class="sb-account-layout"><aside class="sb-account-nav"><button :class="{ active: active === 'overview' }" @click="active = 'overview'"><UserRound :size="18" /> Обзор</button><button :class="{ active: active === 'orders' }" @click="active = 'orders'"><Package :size="18" /> Мои заказы</button><button :class="{ active: active === 'loyalty' }" @click="active = 'loyalty'"><Award :size="18" /> Бонусы</button><button :class="{ active: active === 'addresses' }" @click="active = 'addresses'"><MapPin :size="18" /> Адреса</button><button :class="{ active: active === 'profile' }" @click="active = 'profile'"><Settings :size="18" /> Мои данные</button><button class="logout" @click="signOut"><LogOut :size="18" /> Выйти</button></aside><section class="sb-account-content"><div v-if="loading" class="sb-state">Загружаем кабинет…</div><div v-else-if="error" class="sb-state is-error">{{ error }}</div><template v-else-if="dashboard"><div v-if="active === 'overview'"><div class="sb-account-cards"><article><Package :size="22" /><span>Заказов</span><b>{{ dashboard.summary.orders }}</b></article><article><ShoppingBag :size="22" /><span>Покупок на сумму</span><b>{{ Number(dashboard.summary.spent).toLocaleString('ru-RU') }} ₽</b></article><article><Award :size="22" /><span>Уровень</span><b>{{ dashboard.loyalty.levelLabel }}</b></article></div><div class="sb-account-section"><div class="sb-account-section__head"><h2>Последние заказы</h2><button @click="active = 'orders'">Смотреть все</button></div><div v-if="dashboard.orders.length" class="sb-order-list"><article v-for="order in dashboard.orders.slice(0, 3)" :key="order.id"><div><b>{{ order.orderNumber }}</b><span>{{ new Date(order.createdAt).toLocaleDateString('ru-RU') }}</span></div><span>{{ statuses[order.status] || order.status }}</span><strong>{{ Number(order.finalAmount).toLocaleString('ru-RU') }} ₽</strong></article></div><div v-else class="sb-account-empty">Первый заказ появится здесь. <NuxtLink to="/catalog">Перейти в каталог</NuxtLink></div></div></div><div v-else-if="active === 'orders'" class="sb-account-section"><h2>Мои заказы</h2><div v-if="dashboard.orders.length" class="sb-order-list is-full"><article v-for="order in dashboard.orders" :key="order.id"><div><b>{{ order.orderNumber }}</b><span>{{ new Date(order.createdAt).toLocaleDateString('ru-RU') }} · {{ order.items.length }} поз.</span></div><span>{{ statuses[order.status] || order.status }}</span><strong>{{ Number(order.finalAmount).toLocaleString('ru-RU') }} ₽</strong></article></div><div v-else class="sb-account-empty">Заказов пока нет.</div></div><div v-else-if="active === 'loyalty'" class="sb-account-section"><p class="sb-kicker">SARKISIAN CLUB</p><h2>{{ dashboard.loyalty.balance }} бонусов</h2><p>1 бонус = 1 ₽. Бонусами можно оплачивать часть следующих покупок.</p><div class="sb-loyalty-progress"><span :style="{ width: dashboard.loyalty.progress + '%' }"></span></div><small>Текущий уровень: {{ dashboard.loyalty.levelLabel }} · до следующего уровня {{ dashboard.loyalty.toNextLevel }} бонусов</small><div class="sb-loyalty-history"><article v-for="item in dashboard.loyalty.entries" :key="item.id"><span>{{ item.reason }}<small>{{ new Date(item.createdAt).toLocaleDateString('ru-RU') }}</small></span><b :class="{ minus: item.amount < 0 }">{{ item.amount > 0 ? '+' : '' }}{{ item.amount }}</b></article></div></div><div v-else-if="active === 'addresses'" class="sb-account-section"><h2>Адреса доставки</h2><div v-if="dashboard.addresses.length" class="sb-address-list"><article v-for="address in dashboard.addresses" :key="address.id"><MapPin :size="20" /><span><b>{{ address.label }}</b><small>{{ address.city }}, {{ address.street }}, {{ address.house }}</small></span></article></div><div v-else class="sb-account-empty">Сохранённые адреса появятся после оформления заказа.</div></div><div v-else class="sb-account-section"><h2>Мои данные</h2><div class="sb-profile-grid"><label>Имя<input :value="user?.firstName || ''" readonly /></label><label>Фамилия<input :value="user?.lastName || ''" readonly /></label><label>Email<input :value="user?.email || ''" readonly /></label></div><p>Изменение персональных данных и пароля будет подключено к общей безопасной системе аккаунтов экосистемы.</p></div></template></section></div></div></SiteShell></template>
